    "changeNoteTa": "முழுமையான இருமொழி அறிவியல் கொள்கைகள், சோதனைகள் மற்றும் வரைபடங்கள்.",
    "readTimeMinutes": 14,
    "bodyEn": "### 1. Fundamental Overview\nSound travels as mechanical longitudinal waves; echoes measure distances and Doppler effect shifts frequencies.\n\n### 2. Key Board Concepts\n- **Point 1:** Sound wave velocity: v = f·λ; velocity is fastest in solids and increases with temperature (v_t = v_0 + 0.61t).\n- **Point 2:** Persistence of hearing is 0.1 s; minimum distance to hear a distinct echo is 17.2 m at 20 °C.\n- **Point 3:** Doppler Effect: Apparent shift in observed frequency due to relative motion of source and observer.\n- **Point 4:** Ultrasonics (>20,000 Hz) are utilized in SONAR to map sea depth: d = (v × t) / 2.\n- **Point 5:** Acoustic design of halls prevents excessive reverberation using sound-absorbing acoustic tiles.\n\n### 3. Exam Importance\nThis unit is a regular source of 2-mark and 5-mark questions in the Tamil Nadu SSLC Public Examination.",
    "bodyTa": "### 1. பாட அறிமுகம்\nஒலி நெட்டலைகளாகப் பரவுகிறது; எதிரொலி தூரத்தை அளவிடவும், டாப்ளர் விளைவு அதிர்வெண் மாற்றத்தைக் கணக்கிடவும் உதவுகின்றன.\n\n### 2. முக்கிய பாடக் கருத்துகள்\n- **கருத்து 1:** ஒலியின் திசைவேகம்: v = f·λ; திடப்பொருட்களில் வேகம் அதிகம்; வெப்பநிலை கூடும் போது வேகம் கூடும்.\n- **கருத்து 2:** மனித காதின் நிலைத்திருத்தல் காலம் 0.1 விநாடி; எதிரொலி கேட்க குறைந்தபட்ச தூரம் 17.2 மீ.\n- **கருத்து 3:** டாப்ளர் விளைவு: ஒலி மூலம் மற்றும் கேட்பவரின் சார்பியக்கத்தால் ஏற்படும் தோற்ற அதிர்வெண் மாற்றம்.\n- **கருத்து 4:** சோனார் (SONAR) கடலின் ஆழத்தை அளவிட 20,000 Hz-க்கு அதிகமான மீயொலியைப் பயன்படுத்துகிறது.\n- **கருத்து 5:** அரங்குகளில் அதிக எதிரொலிப்பைத் தவிர்க்க ஒலி உறிஞ்சும் பொருட்கள் பயன்படுத்தப்படுகின்றன.\n\n### 3. தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் கேட்கப்படும் மிக முக்கியமான வினாக்களைக் கொண்டுள்ளது.",
    "rememberBoxes": [
      {
        "tipEn": "Board Exam Drawing Tip: Always use a sharp pencil for neat ray diagrams, cross-sections, and organ sketches with clear labeled arrows.",
        "tipTa": "வரைபட உதவிக்குறிப்பு: அறிவியல் தேர்வில் கதிர் வரைபடங்கள், உள்ளமைப்பு மற்றும் உறுப்பு வரைபடங்களை கூர்மையான பென்சிலால் பாகங்களைக் குறித்து வரையவும்."
      },
      {
        "tipEn": "Formula & Units: State equations with proper SI units (e.g., N, J, W, D, Ω, mol) to secure full step marks.",
        "tipTa": "அளவீட்டு அலகுகள்: கணக்கீடுகளில் சரியான SI அலகுகளைக் குறிப்பிடுவதன் மூலம் முழு மதிப்பெண்களைப் பெறலாம்."
      }
    ],
