    "classLevel": 10,
    "subjectId": "c10_science",
    "titleEn": "Board Revision Notes: Unit 13 - Structural Organisation of Animals",
    "titleTa": "தேர்வு திருப்புதல் குறிப்புகள்: அலகு 13 - உயிரினங்களின் அமைப்பு நிலைகள்",
    "publishedAt": "23 Sep 2026",
    "publishedAtTa": "23 செப் 2026",
    "updatedAt": "23 Sep 2026",
    "updatedAtTa": "23 செப் 2026",
    "syllabusYear": "Samacheer Kalvi 2026–27",
    "syllabusYearTa": "சமச்சீர் கல்வி 2026–27",
    "reviewedBy": "TN SCERT Science Faculty",
    "reviewedByRole": "Senior Science Academic Specialist",
    "reviewedAt": "23 Sep 2026",
    "reviewedAtTa": "23 செப் 2026",
    "status": "published",
    "version": "2.0.0",
    "changeNote": "Comprehensive bilingual theory, experimental setups, definitions, and board diagrams.",
    "changeNoteTa": "முழுமையான இருமொழி அறிவியல் கொள்கைகள், சோதனைகள் மற்றும் வரைபடங்கள்.",
    "readTimeMinutes": 14,
    "bodyEn": "### 1. Fundamental Overview\nMorphology and physiology of Indian Cattle Leech (parasitic annelid) and European Rabbit (herbivorous mammal).\n\n### 2. Key Board Concepts\n- **Point 1:** Leech (Hirudinaria granulosa): Metamerically segmented (33 segments) sanguivorous ectoparasite.\n- **Point 2:** Leech adaptations: Anterior/posterior suckers; saliva contains anticoagulant Hirudin; crop stores blood meals.\n- **Point 3:** Rabbit (Oryctolagus cuniculus): Warm-blooded mammal with hair, pinna, and heterodont dentition.\n- **Point 4:** Rabbit dental formula: I 2/1, C 0/0, PM 3/2, M 3/3 = 28 teeth; Diastema is the canine-less gap.\n- **Point 5:** Rabbit caecum houses cellulose-digesting symbiotic microflora for herbivorous digestion.\n\n### 3. Exam Importance\nThis unit is a regular source of 2-mark and 5-mark questions in the Tamil Nadu SSLC Public Examination.",
    "bodyTa": "### 1. பாட அறிமுகம்\nஇந்திய மாட்டு அட்டை (ஒட்டுண்ணி) மற்றும் முயலின் (தாவர உண்ணி பாலூட்டி) உடலமைப்பு மற்றும் உடலியல் பண்புகள்.\n\n### 2. முக்கிய பாடக் கருத்துகள்\n- **கருத்து 1:** அட்டை (ஹிருடினேரியா கிரானுலோசா): 33 கண்டங்கள் கொண்ட இரத்தம் உறிஞ்சும் புற ஒட்டுண்ணி.\n- **கருத்து 2:** அட்டையின் உமிழ்நீரில் உள்ள ஹிருடின் இரத்தம் உறைவதைத் தடுக்கிறது; தீனிப்பை இரத்தத்தை சேமிக்கிறது.\n- **கருத்து 3:** முயல் (ஓரிக்டோலேகஸ் கியூனிகுலஸ்): வெப்ப இரத்த பாலூட்டி; உடல் ரோமங்கள் கொண்டது.\n- **கருத்து 4:** முயலின் பல் வாய்ப்பாடு: 2033/1023 = 28 பற்கள்; கோரைப்பல் இல்லாத இடைவெளி டயாஸ்டீமா எனப்படும்.\n- **கருத்து 5:** முயலின் குடல்வால் செல்லுலோஸை செரிக்கும் பாக்டீரியாக்களைக் கொண்டுள்ளது.\n\n### 3. தேர்வு முக்கியத்துவம்\nஇப்பாடம் தமிழ்நாடு 10-ஆம் வகுப்பு அரசு பொதுத்தேர்வில் கேட்கப்படும் மிக முக்கியமான வினாக்களைக் கொண்டுள்ளது.",
