        "tipTa": "வரைபட உதவிக்குறிப்பு: அறிவியல் தேர்வில் கதிர் வரைபடங்கள், உள்ளமைப்பு மற்றும் உறுப்பு வரைபடங்களை கூர்மையான பென்சிலால் பாகங்களைக் குறித்து வரையவும்."
